import{_ as d,o as a,c as r,a2 as o}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"设定矛盾自查表","description":"","frontmatter":{},"headers":[],"relativePath":"zh/97-设定矛盾自查表.md","filePath":"zh/97-设定矛盾自查表.md"}'),h={name:"zh/97-设定矛盾自查表.md"};function e(l,t,i,u,n,q){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="设定矛盾自查表" tabindex="-1">设定矛盾自查表 <a class="header-anchor" href="#设定矛盾自查表" aria-label="Permalink to &quot;设定矛盾自查表&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>97</td></tr><tr><td>所属模块</td><td>附录与参考资料</td></tr><tr><td>核心关键词</td><td>矛盾自查、设定一致性、逻辑校验、质量控制、设定维护</td></tr></tbody></table><h2 id="一、说明" tabindex="-1">一、说明 <a class="header-anchor" href="#一、说明" aria-label="Permalink to &quot;一、说明&quot;">​</a></h2><p>设定矛盾自查表是锚点共生文明设定体系的质量控制工具，用于在新设定创作、旧设定修订与文档更新时，系统排查可能存在的设定矛盾与逻辑不一致。本自查表基于SPEC.md中确立的14条核心设定与一致性检查清单编制，涵盖世界观、修炼体系、社会制度、法律体系、生命形态、技术体系、历史纪元、跨位面交互等全部模块。任何新设定或修订内容在正式纳入设定体系前，必须通过本自查表的全部检查项。</p><h2 id="二、核心设定一致性检查" tabindex="-1">二、核心设定一致性检查 <a class="header-anchor" href="#二、核心设定一致性检查" aria-label="Permalink to &quot;二、核心设定一致性检查&quot;">​</a></h2><h3 id="_2-1-宇宙名称与基本概念" tabindex="-1">2.1 宇宙名称与基本概念 <a class="header-anchor" href="#_2-1-宇宙名称与基本概念" aria-label="Permalink to &quot;2.1 宇宙名称与基本概念&quot;">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>检查内容</th><th>通过标准</th><th>常见问题</th></tr></thead><tbody><tr><td>C01</td><td>宇宙名称是否统一</td><td>全文统一使用&quot;万灵衡锚本源宙&quot;或简称&quot;衡元宙&quot;，不得使用其他名称</td><td>混用&quot;宇宙&quot;&quot;万界&quot;&quot;诸天&quot;等非标准名称</td></tr><tr><td>C02</td><td>锚点定义是否一致</td><td>锚点始终定义为&quot;法则网络中的稳定节点&quot;，不得变更其本质属性</td><td>将锚点描述为物品、生物或能量体</td></tr><tr><td>C03</td><td>共生理念是否统一</td><td>共生始终指&quot;不同生命间通过互利协作实现共同进化&quot;，不得偏离反掠夺立场</td><td>将共生描述为同化、吞并或控制</td></tr><tr><td>C04</td><td>核心立场是否一致</td><td>始终坚持&quot;现实为基&quot;原则，不得将虚构设定描述为现实</td><td>混淆虚构与现实的边界</td></tr></tbody></table><h3 id="_2-2-修炼体系一致性" tabindex="-1">2.2 修炼体系一致性 <a class="header-anchor" href="#_2-2-修炼体系一致性" aria-label="Permalink to &quot;2.2 修炼体系一致性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>检查内容</th><th>通过标准</th><th>常见问题</th></tr></thead><tbody><tr><td>C05</td><td>体系总数是否一致</td><td>本源修炼体系总数始终为三百套，不得增减</td><td>出现&quot;三百余套&quot;&quot;数百套&quot;等模糊表述</td></tr><tr><td>C06</td><td>体系分类是否一致</td><td>始终分为六大类（本源推演、生命循环、空间法理、意识升维、共生网络、应用工程），每类五十套</td><td>出现其他分类方式或类别数量不一致</td></tr><tr><td>C07</td><td>本源三基是否一致</td><td>前三套始终为推演迭代（001）、生命循环（002）、空间法理调度（003）</td><td>变更前三套的编号或名称</td></tr><tr><td>C08</td><td>倍增果实设定是否一致</td><td>倍增果实始终是&quot;开局buff&quot;，提供百倍推演增幅，已技术化应用</td><td>将倍增果实描述为天然果实或未技术化</td></tr><tr><td>C09</td><td>修炼境界是否一致</td><td>各体系的境界划分与文档14《修炼境界统一划分》保持一致</td><td>自行发明与统一划分矛盾的境界名称</td></tr><tr><td>C10</td><td>反掠夺立场是否一致</td><td>不得将掠夺式修炼描述为正面或可接受的体系</td><td>为掠夺式修炼辩护或美化</td></tr></tbody></table><h3 id="_2-3-社会与法律一致性" tabindex="-1">2.3 社会与法律一致性 <a class="header-anchor" href="#_2-3-社会与法律一致性" aria-label="Permalink to &quot;2.3 社会与法律一致性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>检查内容</th><th>通过标准</th><th>常见问题</th></tr></thead><tbody><tr><td>C11</td><td>文明分型是否一致</td><td>始终为五种分型（东亚集约、北欧福利、北美多元、欧洲大陆社会、发展中赶超）</td><td>出现第六种分型或变更分型名称</td></tr><tr><td>C12</td><td>法律体系是否一致</td><td>始终为宪法+劳动法+消保法+五部配套法（教育、医疗、住房、环境、反垄断）</td><td>遗漏某部法律或增加未设定的法律</td></tr><tr><td>C13</td><td>治理架构是否一致</td><td>始终为锚点议事会（立法）+共生执行委员会（行政）+共生法院（司法）+锚点监督委员会（监督）</td><td>变更机构名称或权力分配</td></tr><tr><td>C14</td><td>联产承包机制是否一致</td><td>始终以&quot;多劳多得&quot;为核心，资源分配以贡献为依据</td><td>将联产承包描述为平均主义或按需分配</td></tr><tr><td>C15</td><td>20%激活战略是否一致</td><td>始终为前期激活20%众生成为位面至高强者</td><td>变更激活比例或目标</td></tr></tbody></table><h3 id="_2-4-六大顶层公理一致性" tabindex="-1">2.4 六大顶层公理一致性 <a class="header-anchor" href="#_2-4-六大顶层公理一致性" aria-label="Permalink to &quot;2.4 六大顶层公理一致性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>检查内容</th><th>通过标准</th><th>常见问题</th></tr></thead><tbody><tr><td>C16</td><td>六大顶层公理是否统一</td><td>全文统一使用&quot;六大顶层公理&quot;表述，不得再使用&quot;五大顶层公理&quot;&quot;四大顶层公理&quot;&quot;四条碾压基准&quot;等旧称</td><td>仍出现&quot;五大公理&quot;&quot;四基准&quot;等旧口径</td></tr><tr><td>C17</td><td>公理五法则优先是否贯彻</td><td>法则先行、设定自洽高于剧情便利；不得出现为剧情便利而推翻设定的表述</td><td>以&quot;剧情需要&quot;为由修改法则</td></tr><tr><td>C18</td><td>剧情是否绑架设定</td><td>任何扩容与推演必须在既有法则网络内自洽，不得临时新增与前期矛盾的设定</td><td>为圆剧情而吃书、改设定</td></tr><tr><td>C19</td><td>对标篇目是否含新维度</td><td>诸天对标篇目必须包含「设定自洽度、吃书烂尾风险」评判维度</td><td>对标篇目缺失该维度</td></tr><tr><td>C20</td><td>公理口径是否一字不改</td><td>六条公理官方表述与文档00一致，不得改写、增删核心措辞</td><td>自行改写公理条文</td></tr><tr><td>C21</td><td>公理六是否点名</td><td>每篇引论须点名&quot;众生全员无限均等法则&quot;，正文贯穿&quot;人人自带基础无限之力、掠夺失去意义&quot;逻辑</td><td>引论缺公理六或正文未贯穿无限本源逻辑</td></tr><tr><td>C22</td><td>无限本源逻辑是否贯穿</td><td>对标篇目须含「有限资源→掠夺内卷 / 无限本源→掠夺无意义」维度</td><td>对标篇目缺失该维度</td></tr></tbody></table><h2 id="三、跨模块逻辑一致性检查" tabindex="-1">三、跨模块逻辑一致性检查 <a class="header-anchor" href="#三、跨模块逻辑一致性检查" aria-label="Permalink to &quot;三、跨模块逻辑一致性检查&quot;">​</a></h2><h3 id="_3-1-时间线一致性" tabindex="-1">3.1 时间线一致性 <a class="header-anchor" href="#_3-1-时间线一致性" aria-label="Permalink to &quot;3.1 时间线一致性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>检查内容</th><th>通过标准</th><th>常见问题</th></tr></thead><tbody><tr><td>L01</td><td>历史事件时间是否一致</td><td>所有历史事件的时间与文档93《编年史简表》及文档70-79保持一致</td><td>同一事件在不同文档中时间不一致</td></tr><tr><td>L02</td><td>纪元划分是否一致</td><td>纪元名称与起止时间与文档70《纪元划分总表》保持一致</td><td>出现未设定的纪元或变更纪元边界</td></tr><tr><td>L03</td><td>人物所处时期是否一致</td><td>关键人物的活跃时期与文档95《关键人物与组织》保持一致</td><td>人物出现在其不存在的时代</td></tr><tr><td>L04</td><td>技术出现时间是否一致</td><td>各项技术的发明与成熟时间与编年史保持一致</td><td>某项技术在其尚未发明的时代被使用</td></tr></tbody></table><h3 id="_3-2-技术体系一致性" tabindex="-1">3.2 技术体系一致性 <a class="header-anchor" href="#_3-2-技术体系一致性" aria-label="Permalink to &quot;3.2 技术体系一致性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>检查内容</th><th>通过标准</th><th>常见问题</th></tr></thead><tbody><tr><td>T01</td><td>复制镜技术是否一致</td><td>复制镜始终是&quot;不接触原物的1:1复制装置&quot;，复制过程零干扰</td><td>将复制镜描述为可改变原物或需接触原物</td></tr><tr><td>T02</td><td>隔离空间是否一致</td><td>隔离空间始终是&quot;与外部由法则壁垒完全分隔的独立空间&quot;</td><td>将隔离空间描述为普通房间或虚拟空间</td></tr><tr><td>T03</td><td>空间法理修为要求是否一致</td><td>各项空间技术的修为要求与文档13《空间法理调度体系详解》保持一致</td><td>低修为者使用了需要高修为的技术</td></tr><tr><td>T04</td><td>能量单位是否一致</td><td>能量计量统一使用&quot;标准能量单位&quot;，不得使用其他单位</td><td>混用&quot;灵石&quot;&quot;晶币&quot;等非标准能量单位</td></tr></tbody></table><h3 id="_3-3-跨位面与时间规则一致性" tabindex="-1">3.3 跨位面与时间规则一致性 <a class="header-anchor" href="#_3-3-跨位面与时间规则一致性" aria-label="Permalink to &quot;3.3 跨位面与时间规则一致性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>检查内容</th><th>通过标准</th><th>常见问题</th></tr></thead><tbody><tr><td>K01</td><td>先观测后有限干涉是否一致</td><td>所有时间回溯与跨位面操作必须遵循此原则，不得跳过观测阶段</td><td>描述未经观测直接干涉的操作</td></tr><tr><td>K02</td><td>仅回传知识是否一致</td><td>考古产出仅限于抽象知识与信息，不得回传物质、能量或生命体</td><td>描述将文物或样本带回本位面的行为</td></tr><tr><td>K03</td><td>穿梭许可制度是否一致</td><td>所有位面穿梭必须获得相应等级许可，不得无证穿梭</td><td>描述未经许可的擅自穿梭</td></tr><tr><td>K04</td><td>时间悖论分类是否一致</td><td>悖论始终分为弑祖、信息、本体、事件四类，不得增加或变更</td><td>出现未设定的悖论类型</td></tr><tr><td>K05</td><td>位面分类是否一致</td><td>位面始终分为五大类（物质本位、能量显化、意识主导、法则破碎、本源近邻）</td><td>出现其他分类方式</td></tr></tbody></table><h3 id="_3-4-生命与种族一致性" tabindex="-1">3.4 生命与种族一致性 <a class="header-anchor" href="#_3-4-生命与种族一致性" aria-label="Permalink to &quot;3.4 生命与种族一致性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>检查内容</th><th>通过标准</th><th>常见问题</th></tr></thead><tbody><tr><td>S01</td><td>种族分类是否一致</td><td>种族始终分为八大类（人形态、兽形态、植物形态、元素形态、能量形态、意识形态、机械形态、混合形态）</td><td>出现其他分类方式</td></tr><tr><td>S02</td><td>奇特生命处置是否一致</td><td>奇特生命始终按三类标准化处置流程处理</td><td>描述未经流程的随意处置</td></tr><tr><td>S03</td><td>黑暗置换体处置是否一致</td><td>黑暗置换体始终按双魂伦理与四类分支处置规则处理</td><td>描述简单消灭一方灵魂的行为</td></tr><tr><td>S04</td><td>万族平等是否一致</td><td>所有智慧种族在法律面前一律平等，不得有种族歧视设定</td><td>描述某个种族天生低等或应被奴役</td></tr></tbody></table><h2 id="四、文档格式与规范检查" tabindex="-1">四、文档格式与规范检查 <a class="header-anchor" href="#四、文档格式与规范检查" aria-label="Permalink to &quot;四、文档格式与规范检查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>检查内容</th><th>通过标准</th><th>常见问题</th></tr></thead><tbody><tr><td>F01</td><td>文件名格式是否正确</td><td>文件名格式为&quot;XX-文档标题.md&quot;，XX为两位数字编号</td><td>编号缺失、标题含空格、文件扩展名错误</td></tr><tr><td>F02</td><td>文档信息块是否完整</td><td>开头包含编号、所属模块、核心关键词（3-5个）的信息表格</td><td>信息块缺失或字段不全</td></tr><tr><td>F03</td><td>二级标题数量是否达标</td><td>正文至少包含3个二级标题章节</td><td>二级标题少于3个</td></tr><tr><td>F04</td><td>结构化元素是否使用</td><td>使用列表、表格等结构化元素增强可读性</td><td>纯文本段落，无列表或表格</td></tr><tr><td>F05</td><td>结语是否存在</td><td>末尾有&quot;结语&quot;段落</td><td>缺少结语</td></tr><tr><td>F06</td><td>关联文档是否存在</td><td>末尾列出2-3份相关文档编号与名称</td><td>缺少关联文档或关联文档不存在</td></tr><tr><td>F07</td><td>字数是否达标</td><td>正文不少于800字（不含标题和元信息）</td><td>正文不足800字</td></tr><tr><td>F08</td><td>术语使用是否统一</td><td>使用&quot;衡元宙&quot;&quot;锚点&quot;&quot;共生&quot;等标准术语</td><td>术语不统一或使用非标准表述</td></tr><tr><td>F09</td><td>写作风格是否恰当</td><td>严肃、体系化的设定文档风格，无口语化表达</td><td>出现口语化、随意化表达</td></tr><tr><td>F10</td><td>编号是否与清单一致</td><td>文档编号与标题与SPEC.md中的100份文档完整清单一致</td><td>编号或标题与清单不符</td></tr></tbody></table><h2 id="五、自查流程与使用方法" tabindex="-1">五、自查流程与使用方法 <a class="header-anchor" href="#五、自查流程与使用方法" aria-label="Permalink to &quot;五、自查流程与使用方法&quot;">​</a></h2><h3 id="_5-1-新设定创作自查流程" tabindex="-1">5.1 新设定创作自查流程 <a class="header-anchor" href="#_5-1-新设定创作自查流程" aria-label="Permalink to &quot;5.1 新设定创作自查流程&quot;">​</a></h3><ol><li><strong>初步自查</strong>：创作完成后，创作者对照本自查表逐项检查，标记存在问题的项。</li><li><strong>修改完善</strong>：对标记的问题项进行修改，确保全部通过。</li><li><strong>交叉审核</strong>：提交给另一位设定创作者进行交叉审核，重点检查跨模块一致性。</li><li><strong>委员会审定</strong>：重大设定变更须提交设定维护委员会审定。</li><li><strong>归档更新</strong>：通过全部检查后，正式纳入设定体系并更新相关索引文档。</li></ol><h3 id="_5-2-旧设定修订自查流程" tabindex="-1">5.2 旧设定修订自查流程 <a class="header-anchor" href="#_5-2-旧设定修订自查流程" aria-label="Permalink to &quot;5.2 旧设定修订自查流程&quot;">​</a></h3><ol><li><strong>影响评估</strong>：评估修订内容可能影响的其他文档与设定模块。</li><li><strong>关联检查</strong>：对所有受影响的关联文档进行一致性检查。</li><li><strong>同步修订</strong>：对关联文档中受影响的内容进行同步修订。</li><li><strong>版本记录</strong>：在文档99《文档版本与维护说明》中记录修订内容与版本号。</li><li><strong>公告通知</strong>：重大修订须向全体设定使用者发布变更公告。</li></ol><h3 id="_5-3-定期全面自查" tabindex="-1">5.3 定期全面自查 <a class="header-anchor" href="#_5-3-定期全面自查" aria-label="Permalink to &quot;5.3 定期全面自查&quot;">​</a></h3><p>设定维护委员会每季度进行一次全面的设定一致性自查，对全部100份文档进行系统检查，排查潜在的设定矛盾与逻辑不一致。自查结果形成《季度设定一致性报告》，向全体设定使用者公开。</p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>设定矛盾自查表是锚点共生文明设定体系的&quot;质量宪法&quot;。它通过系统化、清单化的检查项，确保设定体系在不断扩展与修订的过程中始终保持逻辑自洽与术语统一。一个庞大的设定体系最怕的不是内容不够丰富，而是内部矛盾丛生、前后不一。本自查表的存在，就是为了让锚点共生文明设定体系在保持开放性与成长性的同时，始终拥有坚实的一致性根基。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>99-文档版本与维护说明</li><li>90-术语词典</li><li>00-衡元宙宇宙总览</li></ul>',35)])])}const _=d(h,[["render",e]]);export{s as __pageData,_ as default};
